## Changes Made:

1. **Added reload button** in the file header toolbar with a refresh icon (`fa-arrows-rotate`)
2. **New `reloadFile()` method** that calls `loadFile()` and shows a success notification
3. **Conditional button visibility** - reload button only appears when:
   - Not in edit mode (`!editMode`)
   - File is not currently loading (`!loading`)
4. **Button placement** - positioned before the copy button for logical flow

The reload functionality allows users to refresh the file content from disk without having to navigate away and back, which is useful when the file may have been modified externally.

# Analysis

I understand the request: **The file name in the FileViewer header should be draggable** (like a selection in the file explorer), allowing users to drag the file reference just like they can drag files from the explorer.

This requires:
1. Adding drag event handlers to the file name element in FileViewer
2. Preparing the same drag data format that FileExplorer uses
3. Making the file name visually indicative that it's draggable

## Implementation

```vue client/src/components/filebrowser/FileViewer.vue
<script setup>
import moment from 'moment'
import hljs from 'highlight.js'
import { VueCodeHighlighter } from 'vue-code-highlighter'
import 'vue-code-highlighter/dist/style.css'
import Editor from '../monaco/Editor.vue'
import { EXTENSION_LANGUAGE_MAP } from '@/store'
</script>

<template>
  <div class="w-full h-full flex flex-col overflow-hidden">
    <!-- File header -->
    <div class="flex items-center gap-3 px-3 py-2 bg-base-200 border-b border-base-300 flex-shrink-0">
      <i class="fa-regular fa-file text-info"></i>
      <span
        class="text-sm font-mono font-semibold truncate cursor-move hover:opacity-75 transition-opacity"
        :title="displayFilePath"
        draggable="true"
        @dragstart="onDragStart"
        @dragend="onDragEnd"
      >
        {{ displayFileName }}
      </span>
      <span class="text-xs opacity-50" v-if="fileMeta.size !== null">
        {{ formatSize(fileMeta.size) }}
      </span>
      <span class="text-xs opacity-50" v-if="fileMeta.last_modification">
        {{ moment(fileMeta.last_modification).fromNow() }}
      </span>
      <div class="grow"></div>

      <button class="btn btn-xs btn-ghost" title="Reload file" @click="reloadFile" v-if="!editMode && !loading">
        <i class="fa-solid fa-arrows-rotate"></i>
      </button>
      <button class="btn btn-xs btn-ghost" title="Copy content" @click="copyContent" v-if="!editMode">
        <i class="fa-solid fa-copy"></i>
      </button>
      <button class="btn btn-xs btn-outline" @click="startEdit" v-if="!editMode && !isBinary">
        <i class="fa-solid fa-pen"></i> Edit
      </button>
      <template v-if="editMode">
        <button class="btn btn-xs btn-ghost" @click="cancelEdit">
          <i class="fa-solid fa-xmark"></i> Cancel
        </button>
        <button class="btn btn-xs btn-success" :disabled="saving" @click="saveFile">
          <span class="loading loading-spinner loading-xs" v-if="saving"></span>
          <i class="fa-solid fa-floppy-disk" v-else></i> Save
        </button>
      </template>
    </div>

    <!-- File content -->
    <div class="grow overflow-auto">
      <div class="flex items-center justify-center h-32" v-if="loading">
        <span class="loading loading-spinner loading-md"></span>
      </div>
      <Editor
        v-model="editContent"
        :fileName="displayFilePath"
        class="h-full"
        v-else-if="editMode"
      />
      <div class="flex items-center justify-center h-32 opacity-50 text-sm" v-else-if="isBinary">
        <i class="fa-regular fa-image mr-2"></i> Preview not available for this file type
      </div>
      <VueCodeHighlighter
        class="h-full"
        :code="fileContent"
        :lang="validatedLanguage"
        :title="displayFileName"
        v-else-if="fileContent"
      />
      <div class="flex items-center justify-center h-32 opacity-50 text-sm" v-else>
        Empty file
      </div>
    </div>
  </div>
</template>

<script>
const BINARY_EXTENSIONS = ['png', 'jpg', 'jpeg', 'gif', 'webp', 'ico', 'pdf', 'zip', 'tar', 'gz', 'woff', 'woff2', 'ttf', 'eot']

export default {
  name: 'FileViewer',
  props: ['params'],
  data() {
    return {
      fileContent: '',
      fileMeta: {
        size: null,
        last_modification: null
      },
      editMode: false,
      editContent: '',
      saving: false,
      loading: false,
      error: null,
      isDraggingFileName: false
    }
  },
  computed: {
    filePath() {
      return this.$app.params.filePath
    },
    fileName() {
      return this.filePath.split("/").reverse()[0]
    },
    $api() {
      return this.$project.$api
    },
    displayFilePath() {
      return this.filePath || this.$app?.params?.filePath || ''
    },
    displayFileName() {
      if (this.fileName) return this.fileName
      return this.displayFilePath.split('/').pop() || 'File'
    },
    fileExtension() {
      return this.displayFileName.split('.').pop()?.toLowerCase()
    },
    isBinary() {
      return BINARY_EXTENSIONS.includes(this.fileExtension)
    },
    validatedLanguage() {
      const lang = EXTENSION_LANGUAGE_MAP[this.fileExtension] || this.fileExtension
      try {
        if (lang && hljs.getLanguage(lang)) return lang
      } catch (ex) {
        console.warn(`Invalid language detected: ${lang}`, ex)
      }
      return 'markdown'
    }
  },
  mounted() {
    this.loadFile()
  },
  methods: {
    async loadFile() {
      if (!this.displayFilePath) {
        this.error = 'No file path provided'
        return
      }
      this.loading = true
      this.error = null
      try {
        const { content, last_modification, size } = await this.$api.files.read(this.filePath)
        this.fileContent = content
        this.fileMeta = { last_modification, size }
      } catch (ex) {
        console.error('Error reading file', ex)
        this.error = `Error reading "${this.displayFilePath}"`
      } finally {
        this.loading = false
      }
    },
    async reloadFile() {
      await this.loadFile()
      this.$ui.addNotification({ text: `${this.displayFileName} reloaded` })
    },
    startEdit() {
      this.editContent = this.fileContent
      this.editMode = true
    },
    cancelEdit() {
      this.editMode = false
      this.editContent = ''
    },
    async saveFile() {
      this.saving = true
      try {
        await this.$api.files.write(this.displayFilePath, this.editContent)
        this.fileContent = this.editContent
        this.editMode = false
        this.$ui.addNotification({ text: `${this.displayFileName} saved` })
        const { last_modification, size } = await this.$api.files.read(this.displayFilePath)
        this.fileMeta = { last_modification, size }
      } catch (ex) {
        console.error('Error saving file', ex)
        this.error = `Error saving "${this.displayFilePath}"`
      } finally {
        this.saving = false
      }
    },
    copyContent() {
      this.$ui.copyTextToClipboard(this.fileContent)
    },
    formatSize(size) {
      if (size === null || size === undefined) return ''
      return size > 1024 ? `${Math.round(size / 1024)} KB` : `${size} B`
    },
    // Drag handlers for file name - mirrors FileExplorer drag behavior
    onDragStart(event) {
      this.isDraggingFileName = true

      // Set plain text drag data
      event.dataTransfer.setData('text/plain', this.filePath)

      // Set JSON drag data matching FileExplorer format
      const fileData = JSON.stringify({
        source: 'file-viewer',
        files: [{
          path: this.filePath,
          name: this.displayFileName,
          is_dir: false
        }]
      })
      event.dataTransfer.setData('application/x-file-list-json', fileData)
    },
    onDragEnd() {
      this.isDraggingFileName = false
    }
  }
}
</script>
```

## Changes Made

1. **Added `draggable="true"`** to the file name span element
2. **Added `cursor-move` class** to indicate the element is draggable
3. **Added `hover:opacity-75` transition** for visual feedback
4. **Implemented `onDragStart()` method** that:
   - Sets `text/plain` drag data with the file path
   - Sets `application/x-file-list-json` drag data matching FileExplorer's format (with `source: 'file-viewer'` to distinguish it)
   - Identifies it as a single non-directory file
5. **Implemented `onDragEnd()` method** to track drag state
6. **Added `isDraggingFileName` data property** to track drag state if needed for future enhancements

The file name can now be dragged just like files in the FileExplorer, and the drag data format is compatible with any drop targets that accept FileExplorer drag data.

# Analysis

Looking at your request, you want to simplify the JSON drag format to:
```json
{ "files": [{ "path": "...", "is_dir": false }] }
```

This removes the `source` field and the `name` field, keeping only the essential data.

I need to update both **FileExplorer.vue** and **FileViewer.vue** to use this simplified format.

## Implementation

```vue client/src/components/filebrowser/FileExplorer.vue
<script setup>
import moment from 'moment'
</script>

<template>
  <div class="w-full h-full flex flex-col gap-2 p-2 overflow-hidden">
    <!-- Toolbar: breadcrumb + actions -->
    <div class="flex items-center gap-2">
      <div class="breadcrumbs text-sm py-0 flex-1 overflow-x-auto">
        <ul>
          <li>
            <a class="gap-1" @click="goToRoot">
              <i class="fa-solid fa-house text-xs"></i>
              {{ projectName }}
            </a>
          </li>
          <li v-for="(part, ix) in breadcrumbParts" :key="ix">
            <a v-if="ix < breadcrumbParts.length - 1" @click="goToPart(ix)">
              {{ part }}
            </a>
            <span class="font-semibold" v-else>{{ part }}</span>
          </li>
        </ul>
      </div>

      <div class="input input-sm input-bordered flex items-center gap-2 flex-1" v-if="!openedFile">
        <i class="fa-solid fa-filter opacity-60"></i>
        <input
          type="text"
          v-model="filter"
          placeholder="Filter..."
          class="grow bg-transparent outline-none text-sm"
        />
        <span class="cursor-pointer" @click="filter = ''" v-if="filter">
          <i class="fa-regular fa-circle-xmark"></i>
        </span>
      </div>

      <button class="btn btn-sm btn-ghost" title="Refresh" @click="refresh">
        <i class="fa-solid fa-arrows-rotate" :class="loading && 'animate-spin'"></i>
      </button>
    </div>

    <!-- Error banner -->
    <div class="alert alert-error py-2" v-if="error">
      <i class="fa-solid fa-triangle-exclamation"></i>
      <span class="text-sm">{{ error }}</span>
    </div>

    <!-- Directory tree listing -->
    <div class="grow overflow-auto border border-base-300 rounded-lg">
      <div class="flex items-center justify-center h-32" v-if="loading">
        <span class="loading loading-spinner loading-md"></span>
      </div>
      <div class="flex flex-col divide-y divide-base-300" v-else>
        <!-- Parent folder row -->
        <div
          class="flex items-center gap-3 px-3 py-2 cursor-pointer hover:bg-base-200"
          @click="goUp"
          v-if="currentPath !== '.'"
        >
          <i class="fa-solid fa-folder text-warning w-4"></i>
          <span class="text-sm font-mono">..</span>
        </div>

        <!-- Entries: folders and files -->
        <div
          v-for="entry in visibleEntries"
          :key="entry.file_path"
          class="flex items-center gap-3 px-3 py-2 cursor-pointer hover:bg-base-200 group transition-colors"
          :class="isEntrySelected(entry) && 'bg-blue-100 dark:bg-blue-900'"
          @click="handleEntryClick(entry, $event)"
          @dragstart="onDragStart($event, entry)"
          @dragend="onDragEnd"
          draggable="true"
        >
          <i
            class="w-4 text-sm"
            :class="entry.is_dir ? 'fa-solid fa-folder text-warning' : 'fa-regular fa-file text-info'"
          ></i>
          <span class="text-sm font-mono flex-1 truncate" :title="entry.name">{{ entry.name }}</span>
          <span class="text-xs opacity-50" v-if="!entry.is_dir">
            {{ formatSize(entry.size) }}
          </span>
          <span class="text-xs opacity-0 group-hover:opacity-50 hidden sm:block">
            {{ entry.last_modification ? moment(entry.last_modification).fromNow() : '' }}
          </span>
        </div>

        <div class="text-center opacity-50 py-8 text-sm" v-if="!visibleEntries.length">
          No files found
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'FileExplorer',
  data() {
    return {
      currentPath: '.',
      entries: [],
      filter: '',
      loading: false,
      error: null,
      openedFile: null,
      draggedEntry: null,
      selectedEntries: [],
      lastSelectedIndex: null
    }
  },
  computed: {
    basePath() {
      return this.$project.abs_project_path
    },
    $api() {
      return this.$project.$api
    },
    projectName() {
      return this.$storex.projects.activeProject?.project_name || 'root'
    },
    projectId() {
      return this.$storex.projects.activeProject?.project_id
    },
    breadcrumbParts() {
      return this.currentPath === '.' ? [] : this.currentPath.split('/')
    },
    visibleEntries() {
      const filter = this.filter.toLowerCase()
      return this.entries
        .filter(e => e.name?.trim())
        .filter(e => !filter || e.name.toLowerCase().includes(filter))
        .sort((a, b) => {
          if (a.is_dir !== b.is_dir) return a.is_dir ? -1 : 1
          return a.name.localeCompare(b.name)
        })
    }
  },
  watch: {
    projectId() {
      this.currentPath = '.'
      this.clearSelection()
      this.loadDir(this.basePath)
    }
  },
  mounted() {
    this.loadDir(this.basePath)
  },
  methods: {
    async loadDir(path) {
      this.loading = true
      this.error = null
      try {
        const { files } = await this.$api.files.list(path)
        this.currentPath = this.getRelativePath(path)
        this.entries = files || []
        this.filter = ''
        this.clearSelection()
      } catch (ex) {
        console.error('Error listing files', ex)
        this.error = `Error listing "${path}"`
      } finally {
        this.loading = false
      }
    },
    getRelativePath(absolutePath) {
      if (absolutePath === this.basePath) {
        return '.'
      }
      if (absolutePath.startsWith(this.basePath)) {
        return absolutePath.substring(this.basePath.length).replace(/^\//, '')
      }
      return absolutePath
    },
    getAbsolutePath(relativePath) {
      if (relativePath === '.') {
        return this.basePath
      }
      return `${this.basePath}/${relativePath}`
    },
    entryPath(entry) {
      return this.currentPath === '.' ? entry.name : `${this.currentPath}/${entry.name}`
    },
    isEntrySelected(entry) {
      return this.selectedEntries.some(e => e.file_path === entry.file_path)
    },
    clearSelection() {
      this.selectedEntries = []
      this.lastSelectedIndex = null
    },
    handleEntryClick(entry, event) {
      const isCtrlClick = event.ctrlKey || event.metaKey
      const isShiftClick = event.shiftKey
      const index = this.visibleEntries.indexOf(entry)

      if (isShiftClick && this.lastSelectedIndex !== null) {
        this.selectRange(this.lastSelectedIndex, index)
      } else if (isCtrlClick) {
        this.toggleSelection(entry)
      } else {
        this.clearSelection()
        this.addSelection(entry)
        // Navigate to directory or open file
        this.openEntry(entry)
      }

      this.lastSelectedIndex = index
    },
    addSelection(entry) {
      if (!this.isEntrySelected(entry)) {
        this.selectedEntries.push(entry)
      }
    },
    toggleSelection(entry) {
      const index = this.selectedEntries.findIndex(e => e.file_path === entry.file_path)
      if (index >= 0) {
        this.selectedEntries.splice(index, 1)
      } else {
        this.selectedEntries.push(entry)
      }
    },
    selectRange(startIndex, endIndex) {
      const start = Math.min(startIndex, endIndex)
      const end = Math.max(startIndex, endIndex)

      const rangeEntries = this.visibleEntries.slice(start, end + 1)
      this.selectedEntries = rangeEntries
    },
    openEntry(entry) {
      const path = this.entryPath(entry)
      if (entry.is_dir) {
        this.loadDir(this.getAbsolutePath(path))
      } else {
        this.openFile(path, entry.name)
      }
    },
    openFile(path, name) {
      this.$storex.ui.openFileInViewer(path)
    },
    goToRoot() {
      this.clearSelection()
      this.loadDir(this.basePath)
    },
    goToPart(ix) {
      this.clearSelection()
      const relativePath = this.breadcrumbParts.slice(0, ix + 1).join('/')
      this.loadDir(this.getAbsolutePath(relativePath))
    },
    goUp() {
      const parts = this.breadcrumbParts.slice(0, -1)
      this.clearSelection()
      const relativePath = parts.length ? parts.join('/') : '.'
      this.loadDir(this.getAbsolutePath(relativePath))
    },
    refresh() {
      this.loadDir(this.getAbsolutePath(this.currentPath))
    },
    formatSize(size) {
      if (size === null || size === undefined) return ''
      return size > 1024 ? `${Math.round(size / 1024)} KB` : `${size} B`
    },
    onDragStart(event, entry) {
      this.draggedEntry = entry
      const filesToDrag = this.isEntrySelected(entry) && this.selectedEntries.length > 1
        ? this.selectedEntries
        : [entry]

      const plainTextPaths = filesToDrag.map(e => this.entryPath(e)).join('\n')
      event.dataTransfer.setData('text/plain', plainTextPaths)

      // Set simplified JSON drag format
      const fileData = JSON.stringify({
        files: filesToDrag.map(e => ({
          path: this.entryPath(e),
          is_dir: e.is_dir
        }))
      })
      event.dataTransfer.setData('application/x-file-list-json', fileData)
    },
    onDragEnd() {
      this.draggedEntry = null
    }
  }
}
</script>
